export const NAV_ITEM_BY_PATH = Object.fromEntries(NAV_TREE.flatMap((g) => g.items).map((i) => [i.path, i]));
export const WORKSPACE_OF_PATH = Object.fromEntries(NAV_TREE.flatMap((g) => g.items.map((i) => [i.path, g.id])));
/** Workspaces reduced to what `can` allows; empty workspaces vanish. */
export function visibleNav(can) {
    return NAV_TREE.map((g) => ({ ...g, items: g.items.filter((i) => i.path === '/' || can(i.path)) })).filter((g) => g.items.length > 0);
}
export const GATE_ME_PATHS = ['/', '/bildirimler', '/operator', '/gorevler', '/onaylar', '/giris-cikislarim', '/rozetlerim'];
export const GATES = [
    { id: 'me', title: 'BENİM KMI', short: 'Benim', icon: 'user', workspaces: [], personalPaths: [...GATE_ME_PATHS] },
    { id: 'perf', title: 'PERFORMANCE CENTER', short: 'Performans', icon: 'grid', workspaces: ['pc'] },
    { id: 'flow', title: 'SİPARİŞTEN SEVKİYATA', short: 'Sipariş', icon: 'truck', workspaces: ['order', 'ship'] },
    { id: 'dept', title: 'DEPARTMANLAR', short: 'Departman', icon: 'factory', workspaces: ['prod', 'plan', 'cam', 'tool', 'qc', 'maint', 'wh', 'buy', 'fin', 'hr'] },
    { id: 'mgmt', title: 'YÖNETİM VE KURUMSAL ZEKÂ', short: 'Yönetim', icon: 'bolt', workspaces: ['intel', 'fin'] },
    { id: 'tools', title: 'ARAÇLAR VE SİSTEM', short: 'Sistem', icon: 'chip', workspaces: ['it'] },
];
/** Gates reduced to what `visible` (already access-filtered workspaces) allows; empty gates vanish. `Ana Sayfa` is in "Benim", not in the Performance gate. */
export function visibleGates(visible, extraMe = []) {
    const wsById = new Map(visible.map((g) => [g.id, g]));
    const byPath = new Map(visible.flatMap((g) => g.items).map((i) => [i.path, i]));
    return GATES.map((g) => {
        if (g.personalPaths) {
            const items = [...g.personalPaths.map((p) => byPath.get(p)).filter((i) => !!i), ...extraMe];
            return { id: g.id, title: g.title, short: g.short, icon: g.icon, sections: items.length ? [{ id: 'me', short: 'Benim', title: 'BENİM İŞLERİM', icon: 'user', items }] : [] };
        }
        const sections = g.workspaces.map((w) => wsById.get(w)).filter((w) => !!w)
            .map((w) => (g.id === 'perf' ? { ...w, items: w.items.filter((i) => i.path !== '/' && i.path !== '/onaylar' && i.path !== '/bildirimler') } : w)).filter((w) => w.items.length > 0);
        return { id: g.id, title: g.title, short: g.short, icon: g.icon, sections };
    }).filter((g) => g.sections.length > 0);
}
/** Which gate a screen belongs to for highlighting: personal paths → Benim; Maliyet/Ekonomi → Yönetim; otherwise the first gate holding its workspace. */
export function gateOfPath(path) {
    if (path === '/maliyet' || path === '/ekonomi')
        return 'mgmt';
    if (GATE_ME_PATHS.includes(path))
        return 'me';
    const ws = WORKSPACE_OF_PATH[path];
    return gateOfWorkspace(ws);
}
export function gateOfWorkspace(ws) {
    if (!ws)
        return 'me';
    return GATES.find((g) => g.workspaces.includes(ws))?.id ?? 'me';
}
/** Operator-simple menu: a user whose only role is OPERATOR sees one short list (their own work), not the factory tree. */
export function isOperatorOnly(roles) { return roles.length > 0 && roles.every((r) => r === 'OPERATOR'); }
export function simpleNav(tree, preferred) {
    const byPath = new Map(tree.flatMap((g) => g.items).map((i) => [i.path, i]));
    const items = preferred.map((p) => byPath.get(p)).filter((i) => !!i);
    return items.length ? [{ id: 'mine', short: 'Benim', title: 'BENİM İŞLERİM', icon: 'user', items }] : tree;
}
/** Remembered "where I was": the last workspace and favourite screens (per browser; never a permission). */
export const NAV_STATE_KEY = 'kmi-nav-state-v1';
export const RECENT_MAX = 6;
export function readNavState(storage) {
    try {
        const v = JSON.parse(storage?.getItem(NAV_STATE_KEY) ?? 'null');
        const clean = (a, n) => Array.isArray(a) ? a.filter((x) => typeof x === 'string' && x in NAV_ITEM_BY_PATH).slice(0, n) : [];
        return { last: typeof v?.last === 'string' ? v.last : null, favorites: clean(v?.favorites, 8), recent: clean(v?.recent, RECENT_MAX) };
    }
    catch {
        return { last: null, favorites: [], recent: [] };
    }
}
export function nextNavState(prev, ev) {
    const favorites = ev.toggleFavorite && ev.toggleFavorite in NAV_ITEM_BY_PATH
        ? (prev.favorites.includes(ev.toggleFavorite) ? prev.favorites.filter((f) => f !== ev.toggleFavorite) : [...prev.favorites, ev.toggleFavorite].slice(-8))
        : prev.favorites;
    const ws = ev.visit ? WORKSPACE_OF_PATH[ev.visit] : undefined;
    // "recently used": the home page is not a destination worth remembering; a screen moves to the front, duplicates collapse
    const recent = ev.visit && ev.visit !== '/' && ev.visit in NAV_ITEM_BY_PATH ? [ev.visit, ...prev.recent.filter((r) => r !== ev.visit)].slice(0, RECENT_MAX) : prev.recent;
    return { last: ws && ws !== 'pc' ? ws : prev.last, favorites, recent };
}
/** Breadcrumb for a screen: workspace › page (the home page has none). */
/** Display form of a department title: Turkish title case, short acronyms (CAM, İK) and '&' kept. The data titles stay as registered (tests/lookups); only what the user reads is softened. */
export function trTitle(t) {
    return t.split(' ').map((w) => (w.length <= 3 || !/[A-ZÇĞİÖŞÜ]/.test(w) ? w : w.charAt(0) + w.slice(1).toLocaleLowerCase('tr-TR'))).join(' ');
}
/** Detail / helper routes that are not menu entries still get a location line, so no screen is without a "where am I". ws = '' means directly under Ana Sayfa. */
export const DETAIL_CRUMBS = {
    '/pasaport-calisma': { ws: '', page: 'Dijital pasaport' }, '/kart': { ws: '', page: 'Dijital pasaport' }, '/urun-calisma': { ws: 'cam', page: 'Ürün Çalışma Alanı' }, '/is-karti': { ws: 'prod', page: 'İş kartı' },
    '/musteriler-liste': { ws: 'order', page: 'Müşteriler (liste)' }, '/personel-liste': { ws: 'hr', page: 'Personel yönetimi (liste)' }, '/urun-liste': { ws: 'cam', page: 'Ürün Master listesi' },
    '/varlik': { ws: 'prod', page: 'Varlık pasaportu' }, '/ara': { ws: '', page: 'Arama' }, '/nesne': { ws: '', page: 'Nesne pasaportu' },
    '/muhasebe': { ws: 'fin', page: 'Muhasebe / Fatura (kalem)' }, '/tedarikci-fatura': { ws: 'buy', page: 'Tedarikçi Faturası' },
    '/etiket': { ws: 'wh', page: 'Etiket' }, '/malzeme': { ws: 'wh', page: 'Hammadde / BOM' }, '/takim-hazirlik': { ws: 'tool', page: 'Takım Hazırlığı' },
};
export function breadcrumbOf(path) {
    if (path === '/')
        return null;
    const ws = WORKSPACE_OF_PATH[path];
    const item = NAV_ITEM_BY_PATH[path];
    if (!ws || !item) {
        const d = DETAIL_CRUMBS[path];
        if (!d)
            return null;
        const g = d.ws ? NAV_TREE.find((x) => x.id === d.ws) : undefined;
        return { workspace: g?.title ?? '', workspaceId: g?.id ?? '', page: d.page };
    }
    const g = NAV_TREE.find((x) => x.id === ws);
    return { workspace: g.title, workspaceId: g.id, page: item.label };
}
/** Inline SVG markup for an icon (static, trusted strings only). */
export function iconSvg(name, size = 20) {
    return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="${ICON_PATHS[name]}"/></svg>`;
}
